import { CommonModule } from '@angular/common';
import { Component, Input, SecurityContext, inject } from '@angular/core';
import { DomSanitizer } from '@angular/platform-browser';
import { ReplaySubject, shareReplay, switchMap } from 'rxjs';
import { AlertService } from '../../common/alert/alert.service';
import { StorageService } from '../../common/storage/storage.service';

@Component({
    selector: 'app-avatar',
    templateUrl: './avatar.component.html',
    styleUrls: ['./avatar.component.scss'],
    imports: [CommonModule]
})
export class AvatarComponent {
  private readonly alertService = inject(AlertService);
  private readonly dom = inject(DomSanitizer);
  private readonly storageService = inject(StorageService);

  @Input()
  set avatarUrl(url: string | null | undefined) {
    this.avatarUrlSubject.next(url);
  }
  @Input() disabled = false;
  @Input() showBorder = true;

  personIcon = 'node_modules/openmoji/color/svg/1F464.svg'; // 👤 Bust in Silhouette

  private readonly avatarUrlSubject = new ReplaySubject<string | null | undefined>(1);

  avatarUrl$ = this.avatarUrlSubject.asObservable().pipe(
    switchMap(async (url) => this.downloadImage(url)),
    shareReplay(1)
  );

  private async downloadImage(path: string | undefined | null) {
    try {
      if (!path) {
        return undefined;
      }

      if (path.startsWith('http')) {
        return path;
      }

      const data = await this.storageService.download('avatars', path);

      if (!data) {
        return undefined;
      }

      const sanitizedUrl = this.dom.sanitize(
        SecurityContext.URL,
        URL.createObjectURL(data)
      );

      return sanitizedUrl || '';
    } catch (error: unknown) {
      const message = (error as Error)?.message || 'Unknown error';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
        color: 'danger',
      });
      return undefined;
    }
  }
}
